import {useEffect,useMemo,useState} from 'react';
import {ArrowDownToLine,ArrowUpFromLine,ArrowUpDown,BookOpen,Building2,ChevronDown,ChevronUp,Handshake,Landmark,ListChecks,LogOut,Plus,Search,ScrollText,Shield,Trash2,Users,WalletCards,type LucideIcon} from 'lucide-react';
import ResourceIcon from './ResourceIcon';
import './alliance-facelift.css';
import './alliance-treaties.css';
import './alliance-role-editor.css';
import './alliance-management-scale.css';
import './alliance-settings-editor.css';
import './alliance-member-activity.css';
import './alliance-bank-layout.css';
import './alliance-military-overview.css';
import './alliance-membership-actions.css';

const call=async(path:string,options?:RequestInit)=>{const response=await fetch('/api'+path,{credentials:'include',headers:{'Content-Type':'application/json'},...options}),text=await response.text();let data:any={};try{data=text?JSON.parse(text):{}}catch{const message=text.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();throw Error(message.slice(0,240)||`Invalid Alliance response (${response.status}).`)}if(!response.ok)throw Error(data.error||'Request failed');return data};
const taxBracketPayload=(form:HTMLFormElement)=>{const fields=new FormData(form);return{name:String(fields.get('name')||'').trim(),cashRate:Number(fields.get('cashRate')),resourceRate:Number(fields.get('resourceRate'))}};
const resources=['cash','foodstuffs','timber','fibers','basic_metals','energy','strategic_minerals','textiles','processed_foods','construction_materials','basic_goods','consumer_goods','military_equipment','luxury_goods'];
const label=(value:string)=>value.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const go=(path:string)=>{history.pushState(null,'',path);window.dispatchEvent(new PopStateEvent('popstate'))};
const allianceAge=(createdAt:string)=>{const days=Math.max(0,Math.floor((Date.now()-new Date(createdAt).getTime())/86400000));if(days<365)return `${days} ${days===1?'day':'days'}`;const years=Math.floor(days/365),remaining=days%365;return `${years} ${years===1?'year':'years'}${remaining?`, ${remaining} days`:''}`};
const relativeActivity=(raw?:string)=>{if(!raw)return 'No recorded activity';const seconds=Math.max(0,Math.floor((Date.now()-new Date(raw).getTime())/1000));if(seconds<60)return 'Less than a minute ago';const minutes=Math.floor(seconds/60);if(minutes<60)return `${minutes} ${minutes===1?'minute':'minutes'} ago`;const hours=Math.floor(minutes/60);if(hours<24)return `${hours} ${hours===1?'hour':'hours'} ago`;const days=Math.floor(hours/24);return `${days} ${days===1?'day':'days'} ago`};
function AllianceFlag({id,name,className='' }:{id:string;name:string;className?:string}){return <img className={'alliance-flag '+className} src={`/api/alliances/${encodeURIComponent(id)}/flag`} alt={`${name} flag`}/>}

export default function AllianceScreen({mode='directory',allianceID}:{mode?:'directory'|'mine';allianceID?:string}){
 const[data,setData]=useState<any>(),[detail,setDetail]=useState<any>(),[error,setError]=useState(''),[page,setPage]=useState(1),[search,setSearch]=useState('');
 const open=async(id:string,navigate=false)=>{const next=await call('/alliances/'+id);setDetail(next);if(navigate)go('/alliance/'+encodeURIComponent(id))};
 const load=async()=>{try{setError('');const directory=await call('/alliances'+(mode==='directory'?'?search='+encodeURIComponent(search):''));setData(directory);if(mode==='directory')setPage(1);if(allianceID&&mode==='directory')await open(allianceID);else if(mode==='mine'&&directory.membership)await open(directory.membership.allianceID);else setDetail(undefined)}catch(e){setError((e as Error).message)}};useEffect(()=>{const timer=setTimeout(()=>void load(),mode==='directory'?250:0);return()=>clearTimeout(timer)},[mode,allianceID,search]);
 if(!data)return <section className="panel wide">Loading Alliances…</section>;
 if(mode==='mine'&&!data.membership)return <section className="panel wide"><Shield/><span className="eyebrow">MY ALLIANCE</span><h2>Your nation is independent</h2><p>Browse the Alliance List to join or establish an organization.</p></section>;
 if(detail)return <AllianceDetail data={detail} back={()=>go('/alliances')} reload={()=>open(detail.alliance.ID)} exited={()=>{setDetail(undefined);go('/alliances');void load()}}/>;
 const pages=Math.max(1,Math.ceil(data.alliances.length/10)),visible=data.alliances.slice((page-1)*10,page*10);
 return <section className="alliance-directory-page"><section className="alliance-hero"><Shield/><div><span className="eyebrow">PLAYER ORGANIZATIONS · SORTED BY POPULATION</span><h2>Alliance directory</h2><p>Shared taxation, banking, specialization, and diplomacy.</p></div></section>{error&&<p className="error notice">{error}</p>}{!data.membership&&<CreateAlliance reload={load}/>}<label className="alliance-directory-search"><Search/><span>Search Alliances</span><input type="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search Alliance names…"/></label><div className="alliance-grid">{visible.map((alliance:any)=><button className="panel alliance-card" onClick={()=>open(alliance.id,true)} key={alliance.id}><div className="alliance-card-heading"><div><span className="eyebrow">{alliance.joinPolicy.replace('_' ,' ')} · Founded {new Date(alliance.createdAt).toLocaleDateString()}</span><h3>{alliance.name}</h3></div><AllianceFlag id={alliance.id} name={alliance.name} className="alliance-card-flag"/></div><div className="alliance-card-stats"><span><b>{alliance.members}</b> nations</span><span><b>{Number(alliance.provinces||0).toLocaleString()}</b> provinces</span></div><small>Total population <b>{Number(alliance.population).toLocaleString()}</b></small></button>)}</div>{!visible.length&&<section className="panel alliance-directory-empty"><Search/><h3>No Alliances found</h3><p>Try a different Alliance name.</p></section>}{pages>1&&<nav className="directory-pager" aria-label="Alliance directory pages"><button disabled={page===1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {pages} · {data.alliances.length} Alliances</span><button disabled={page===pages} onClick={()=>setPage(page+1)}>Next</button></nav>}</section>;
}

function CreateAlliance({reload}:{reload:()=>Promise<void>}){const[open,setOpen]=useState(false),[error,setError]=useState('');if(!open)return <button className="primary create-alliance" onClick={()=>setOpen(true)}><Plus/>Create an Alliance</button>;return <form className="panel alliance-create" onSubmit={async e=>{e.preventDefault();try{await call('/alliances',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});await reload()}catch(x){setError((x as Error).message)}}}><h2>Establish an Alliance</h2><label>Name<input name="name" minLength={3} maxLength={80} required/></label><label>Public description<textarea name="description" maxLength={1000}/></label><label>Membership<select name="joinPolicy"><option value="apply">Applications</option><option value="open">Open membership</option><option value="invite_only">Invite only</option></select></label>{error&&<p className="error">{error}</p>}<button className="primary">Create Alliance</button></form>}

function AllianceDetail({data,back,reload,exited}:{data:any;back:()=>void;reload:()=>Promise<void>;exited:()=>void}){
 const alliance=data.alliance,[tab,setTab]=useState('overview'),[error,setError]=useState(''),storageKey=`diplomatia:alliance-description:${alliance.ID}`,[descriptionHidden,setDescriptionHidden]=useState(()=>localStorage.getItem(storageKey)==='hidden');
 const mutate=async(path:string,method='POST',body?:object)=>{setError('');try{await call(path,{method,body:body?JSON.stringify(body):undefined});window.dispatchEvent(new Event('diplomatia:resources'));await reload()}catch(e){setError((e as Error).message)}};
 const totalPopulation=data.members.reduce((sum:number,m:any)=>sum+Number(m.population||0),0),totalProvinces=data.members.reduce((sum:number,m:any)=>sum+Number(m.provinces||0),0);
 const tabs:Array<[string,string,LucideIcon]>=[['overview','Overview',BookOpen],['members','Members',Users],...(data.permissions&&(data.permissions.viewBank||data.permissions.deposit||data.permissions.withdraw)?[['bank','Bank',Landmark] as [string,string,LucideIcon]]:[]),...(data.permissions?.audit?[['logs','Bank Logs',ScrollText] as [string,string,LucideIcon]]:[]),...(data.permissions?.tax?[['tax','Tax Policy',WalletCards] as [string,string,LucideIcon],['tax-history','Tax History',ScrollText] as [string,string,LucideIcon]]:[]),...(data.permissions?.roles?[['roles','Roles & Permissions',ListChecks] as [string,string,LucideIcon]]:[]),...(data.permissions?.applicants?[['applications','Applications',ScrollText] as [string,string,LucideIcon]]:[])];
 return <div className="alliance-detail-page"><button className="back" onClick={back}>← Alliance directory</button><section className="alliance-masthead"><AllianceFlag id={alliance.ID} name={alliance.Name} className="alliance-masthead-flag"/><div><span className="eyebrow">FOUNDED {new Date(alliance.CreatedAt).toLocaleDateString()} / {allianceAge(alliance.CreatedAt)} OLD</span><h2>{alliance.Name}</h2><p>{data.permissions?.role?`Serving as ${data.permissions.role}`:'Public Alliance profile'}</p></div><div className="masthead-policy"><span>{alliance.JoinPolicy.replace('_',' ')}</span><b>{data.members.length} nations</b></div></section><section className={'alliance-description '+(descriptionHidden?'collapsed':'')}><header><span className="eyebrow">ALLIANCE CHARTER</span><button onClick={()=>{const next=!descriptionHidden;setDescriptionHidden(next);localStorage.setItem(storageKey,next?'hidden':'shown')}}>{descriptionHidden?<><ChevronDown/>Show custom description</>:<><ChevronUp/>Hide custom description</>}</button></header>{!descriptionHidden&&<SafeAllianceDescription text={alliance.Description}/>}</section><div className="alliance-stat-strip"><Stat label="Nations" value={String(data.members.length)}/><Stat label="Total Provinces" value={totalProvinces.toLocaleString()}/><Stat label="Total Population" value={totalPopulation.toLocaleString()}/><Stat label="Founded" value={new Date(alliance.CreatedAt).toLocaleDateString()}/></div>{error&&<p className="error notice">{error}</p>}<nav className="alliance-tabs">{tabs.map(([key,name,Icon])=><button className={tab===key?'active':''} onClick={()=>setTab(key)} key={key}><Icon/>{name}</button>)}</nav>{tab==='overview'&&<AllianceOverview data={data} mutate={mutate} exited={exited}/>} {tab==='members'&&<MembersTab data={data} mutate={mutate}/>} {tab==='bank'&&<BankTab data={data} mutate={mutate} reload={reload}/>} {tab==='tax'&&<TaxTab data={data} mutate={mutate}/>} {tab==='tax-history'&&<TaxHistory data={data}/>} {tab==='roles'&&<RolesTab data={data} mutate={mutate}/>} {tab==='applications'&&<ApplicationsTab data={data} mutate={mutate}/>} {tab==='logs'&&<BankLogs data={data}/>}<AllianceShare alliance={alliance}/></div>;
}

function SafeAllianceDescription({text}:{text:string}){const html=useMemo(()=>{let safe=(text||'No public charter has been published.').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');safe=safe.replace(/\[b\]([\s\S]*?)\[\/b\]/gi,'<strong>$1</strong>').replace(/\[i\]([\s\S]*?)\[\/i\]/gi,'<em>$1</em>').replace(/\[u\]([\s\S]*?)\[\/u\]/gi,'<u>$1</u>').replace(/\[color=(#[0-9a-fA-F]{3,6})\]([\s\S]*?)\[\/color\]/gi,'<span style="color:$1">$2</span>').replace(/\[url=(https?:\/\/[^\]\s]+)\]([\s\S]*?)\[\/url\]/gi,'<a href="$1" target="_blank" rel="noopener noreferrer">$2</a>').replace(/\[list\]([\s\S]*?)\[\/list\]/gi,(_,body)=>'<ul>'+body.replace(/\[\*\]([^\[]+)/g,'<li>$1</li>')+'</ul>').replaceAll('\n','<br/>');return safe},[text]);return <div className="alliance-rich-description" dangerouslySetInnerHTML={{__html:html}}/>}
function Stat({label,value}:{label:string;value:string}){return <div><span>{label}</span><b>{value}</b></div>}
function ListPager({page,total,setPage,label}:{page:number;total:number;setPage:(page:number)=>void;label:string}){const pages=Math.max(1,Math.ceil(total/10));if(pages<=1)return null;return <nav className="directory-pager" aria-label={`${label} pages`}><button disabled={page===1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {pages} · {total} entries</span><button disabled={page===pages} onClick={()=>setPage(page+1)}>Next</button></nav>}

function AllianceOverview({data,mutate,exited}:{data:any;mutate:Function;exited:()=>void}){const a=data.alliance,totalPopulation=data.members.reduce((sum:number,m:any)=>sum+Number(m.population||0),0),totalProvinces=data.members.reduce((sum:number,m:any)=>sum+Number(m.provinces||0),0),highestRank=Math.max(...data.members.map((m:any)=>Number(m.rank||0)),0),leaders=data.members.filter((m:any)=>Number(m.rank||0)===highestRank).map((m:any)=>m.name).join(', ')||'No leadership recorded',units=[['soldiers','Soldiers'],['tanks','Tanks'],['ships','Ships'],['jets','Fighter Jets'],['drones','Drones']],exitAlliance=async()=>{const sole=data.members.length===1,message=sole?'Delete this Alliance permanently? All Alliance cash and resources will first be transferred to your nation.':'Leave this Alliance?';if(!confirm(message))return;await call(`/alliances/${a.ID}${sole?'':'/leave'}`,{method:sole?'DELETE':'POST'});window.dispatchEvent(new Event('diplomatia:resources'));exited()};return <><div className="alliance-overview-grid"><section className="panel"><span className="eyebrow">ALLIANCE OVERVIEW</span><h2>Organization at a glance</h2><div className="overview-facts"><Stat label="Nations" value={String(data.members.length)}/><Stat label="Founded" value={new Date(a.CreatedAt).toLocaleDateString()}/><Stat label="Alliance age" value={allianceAge(a.CreatedAt)}/><Stat label="Total Provinces" value={totalProvinces.toLocaleString()}/><Stat label="Total Population" value={totalPopulation.toLocaleString()}/><Stat label="Leadership" value={leaders}/><Stat label="Join policy" value={a.JoinPolicy.replace('_',' ')}/><Stat label="Active treaties" value={String(data.treaties?.length||0)}/>{a.CommunityURL&&<div><span>Community</span><b><a href={a.CommunityURL} target="_blank" rel="noreferrer">Open community link</a></b></div>}</div><h3>Combined military inventory</h3><div className="alliance-military-summary">{units.map(([key,name])=><div key={key}><span>{name}</span><b>{Number(data.military?.[key]||0).toLocaleString()}</b></div>)}</div>{data.permissions?.tax&&<><h3>Tax policy summary</h3>{data.taxBrackets.map((b:any)=><div className="tax-summary" key={b.id}><b>{b.name}{b.isDefault?' - Default':''}</b><span>{b.cashRate}% cash / {b.resourceRate}% commodities · {b.assignedCount||0} assigned</span></div>)}</>}</section>{data.permissions?.edit&&<AllianceSettings alliance={a} save={(body:any)=>mutate(`/alliances/${a.ID}`,'PATCH',body)} reload={()=>window.location.reload()}/>}</div><TreatiesTab data={data} mutate={mutate}/>{data.isMember&&<section className="panel alliance-membership-actions"><div><span className="eyebrow">MEMBERSHIP</span><h3>{data.members.length===1?'Dissolve Alliance':'Leave Alliance'}</h3><p>{data.members.length===1?'As the sole member, you may dissolve the Alliance. Its bank cash and resources will be transferred to your nation first.':'Your nation will be removed from the Alliance. If you are its only leader, leadership will pass to the longest-serving remaining member.'}</p></div><button className="danger" onClick={()=>void exitAlliance()}>{data.members.length===1?<><Trash2/>Delete Alliance</>:<><LogOut/>Leave Alliance</>}</button></section>}</>}

function Announcements({data,mutate}:{data:any;mutate:Function}){return <section className="panel alliance-announcements"><span className="eyebrow">ALLIANCE ANNOUNCEMENTS</span><h2>Leadership dispatches</h2>{data.permissions?.announcements&&<form onSubmit={e=>{e.preventDefault();mutate(`/alliances/${data.alliance.ID}/announcements`,'POST',Object.fromEntries(new FormData(e.currentTarget)))}}><input name="title" placeholder="Announcement title" maxLength={120} required/><textarea name="body" placeholder="Write an Alliance announcement…" maxLength={2000} required/><button className="primary">Publish announcement</button></form>}{data.announcements?.length?data.announcements.map((item:any)=><article key={item.id}><header><b>{item.title}</b><time>{new Date(item.createdAt).toLocaleString()}</time></header><p>{item.body}</p><small>Posted by {item.author}</small></article>):<p>No Alliance announcements have been posted.</p>}</section>}

function TreatiesTab({data,mutate}:{data:any;mutate:Function}){const[indefinite,setIndefinite]=useState(true),aid=data.alliance.ID;return <section className="panel treaty-section"><div className="tab-heading"><div><span className="eyebrow">PUBLIC DIPLOMATIC RECORD</span><h2><Handshake/> Alliance treaties</h2></div><span>{data.treaties.length} active</span></div><p className="treaty-disclaimer">Treaties are diplomatic declarations and are not currently enforced by game mechanics.</p><div className="treaty-grid">{data.treaties.length?data.treaties.map((t:any)=><article className="treaty-card" key={t.id}><header><b>{t.acronym}</b><span>{t.indefinite?'Indefinite':`Through ${t.endsOn}`}</span></header><h3>{t.name}</h3><p><AllianceInline alliance={t.allianceA}/> ↔ <AllianceInline alliance={t.allianceB}/></p><small>{t.definition}</small>{t.terms&&<blockquote>{t.terms}</blockquote>}{data.permissions?.war&&<button className="danger" onClick={()=>confirm('Cancel this treaty?')&&mutate(`/alliances/${aid}/treaties/${t.id}`,'DELETE')}>Cancel treaty</button>}</article>):<p>No active treaties.</p>}</div>{data.permissions?.war&&<div className="treaty-management"><h3>Treaty proposals</h3>{data.treatyProposals.map((t:any)=><div className="treaty-proposal" key={t.id}><div><b>{t.acronym} · {t.name}</b><span><AllianceInline alliance={t.allianceA}/> ↔ <AllianceInline alliance={t.allianceB}/></span><small>{t.indefinite?'Indefinite term':`${t.durationDays} server days`}</small></div>{t.proposedByAllianceID===aid?<button className="danger" onClick={()=>mutate(`/alliances/${aid}/treaties/${t.id}`,'DELETE')}>Withdraw</button>:<div><button className="primary" onClick={()=>mutate(`/alliances/${aid}/treaties/${t.id}/accept`)}>Accept</button><button className="danger" onClick={()=>mutate(`/alliances/${aid}/treaties/${t.id}/reject`)}>Reject</button></div>}</div>)}<details className="new-treaty"><summary><Plus/>Propose a treaty</summary><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate(`/alliances/${aid}/treaties`,'POST',{allianceName:f.get('allianceName'),treatyType:f.get('treatyType'),terms:f.get('terms'),indefinite,durationDays:indefinite?0:Number(f.get('durationDays'))})}}><label>Partner Alliance<input name="allianceName" placeholder="Enter exact Alliance name" required/></label><label>Treaty type<select name="treatyType" required>{data.treatyTypes.map((t:any)=><option value={t.key} key={t.key}>{t.acronym} — {t.name}</option>)}</select></label><label className="treaty-duration"><input type="checkbox" checked={indefinite} onChange={e=>setIndefinite(e.target.checked)}/> Indefinite</label>{!indefinite&&<label>Server days<input name="durationDays" type="number" min="1" max="3650" defaultValue="30" required/></label>}<label>Additional public terms<textarea name="terms" maxLength={5000}/></label><div className="treaty-catalog">{data.treatyTypes.map((t:any)=><p key={t.key}><b>{t.acronym}</b> {t.definition}</p>)}</div><button className="primary">Send proposal</button></form></details></div>}</section>}
function AllianceInline({alliance}:{alliance:any}){return <a href={`/alliance/${alliance.id}`} onClick={e=>{e.preventDefault();go(`/alliance/${alliance.id}`)}}>{alliance.name}</a>}

function MembersTab({data,mutate}:{data:any;mutate:Function}){const[sort,setSort]=useState('rank'),[role,setRole]=useState('');const members=[...data.members].filter((m:any)=>!role||m.roleID===role).sort((a:any,b:any)=>sort==='population'?b.population-a.population:sort==='provinces'?b.provinces-a.provinces:sort==='seniority'?b.seniorityDays-a.seniorityDays:sort==='activity'?new Date(b.lastActiveAt||0).getTime()-new Date(a.lastActiveAt||0).getTime():b.rank-a.rank);return <section className="panel members-panel"><div className="tab-heading"><div><span className="eyebrow">ALLIANCE ROSTER</span><h2>{members.length} members</h2></div><div className="member-filters"><select value={role} onChange={e=>setRole(e.target.value)}><option value="">All roles</option>{data.roles.filter((r:any)=>r.defaultKey!=='applicant').map((r:any)=><option value={r.id} key={r.id}>{r.title}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="rank">Rank</option><option value="population">Population</option><option value="provinces">Provinces</option><option value="seniority">Seniority</option><option value="activity">Last Active</option></select><ArrowUpDown/></div></div><div className="member-table head"><span>Nation</span><span>Provinces</span><span>Population</span><span>Role</span><span>Joined</span><span>Seniority</span><span>Last Active</span><span/></div>{members.map((m:any)=><div className="member-table" key={m.nationID}><a className="member-nation-link" href={`/nation/${m.nationID}`} onClick={e=>{e.preventDefault();go(`/nation/${m.nationID}`)}}><b>{m.name}</b><small>Leader · {m.leaderName}</small></a><b>{m.provinces}</b><b>{Number(m.population).toLocaleString()}</b><span>{m.role}</span><time>{new Date(m.joinedAt).toLocaleDateString()}</time><span>{m.seniorityDays} days</span><time className="member-last-active" title={m.lastActiveAt?new Date(m.lastActiveAt).toLocaleString():'No recorded activity'}>{relativeActivity(m.lastActiveAt)}</time><div>{data.permissions?.promote&&m.rank<data.permissions.rank&&<select value={m.roleID} onChange={e=>mutate(`/alliances/${data.alliance.ID}/members/${m.nationID}/role`,'PATCH',{roleID:e.target.value})}>{data.roles.filter((r:any)=>r.rank<data.permissions.rank&&r.defaultKey!=='applicant').map((r:any)=><option value={r.id} key={r.id}>{r.title}</option>)}</select>}{data.permissions?.remove&&m.rank<data.permissions.rank&&<button className="danger" onClick={()=>confirm(`Remove ${m.name}?`)&&mutate(`/alliances/${data.alliance.ID}/members/${m.nationID}`,'DELETE')}>Remove</button>}</div></div>)}</section>}

const bankResourceIcons:Record<string,React.ComponentProps<typeof ResourceIcon>['type']>={cash:'cash',foodstuffs:'foodstuffs',timber:'timber',fibers:'fibers',basic_metals:'basic_metals',energy:'energy',strategic_minerals:'strategic_minerals',textiles:'textiles',processed_foods:'processed_foods',construction_materials:'construction_materials',basic_goods:'basic_goods',consumer_goods:'consumer_goods',military_equipment:'military_equipment',luxury_goods:'luxury_goods'};
const bankAmount=(value:number,cash=false)=>`${cash?'¥':''}${value.toLocaleString(undefined,{minimumFractionDigits:cash?0:1,maximumFractionDigits:3})}${cash?'':' t'}`;
function LegacyBankTab({data,mutate,reload}:{data:any;mutate:Function;reload:()=>Promise<void>}){
 const[available,setAvailable]=useState<Record<string,number>>({}),[amounts,setAmounts]=useState<Record<string,string>>({}),[memo,setMemo]=useState(''),[resource,setResource]=useState('cash'),[amount,setAmount]=useState(1000),[recipient,setRecipient]=useState(data.permissions.nationID),[payoutKind,setPayoutKind]=useState<'withdrawal'|'grant'>('withdrawal'),[operationTab,setOperationTab]=useState<'withdraw'|'adjust'>('withdraw'),[adjustNation,setAdjustNation]=useState(data.permissions.nationID),[adjustResource,setAdjustResource]=useState('cash'),[adjustAmount,setAdjustAmount]=useState(0),[adjustDirection,setAdjustDirection]=useState<'add'|'subtract'>('add'),[adjustMemo,setAdjustMemo]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState('');
 const loadAvailable=async()=>{const[me,strategy]=await Promise.all([call('/me'),call('/strategy')]);setAvailable({cash:Number(me.nation?.Treasury||0),...(strategy.stockpiles||{})})};
 useEffect(()=>{if(data.permissions.deposit)void loadAvailable().catch(e=>setError((e as Error).message))},[data.alliance.ID,data.permissions.deposit]);
 const selected=Object.fromEntries(resources.map(key=>[key,Number(amounts[key]||0)]).filter(([,value])=>Number(value)>0));
 const deposit=async(e:React.FormEvent)=>{e.preventDefault();if(!Object.keys(selected).length){setError('Enter at least one deposit amount.');return}setBusy(true);setError('');setSuccess('');try{await call(`/alliances/${data.alliance.ID}/bank`,{method:'POST',body:JSON.stringify({kind:'deposit',deposits:selected,memo})});setAmounts({});setMemo('');setSuccess(`${Object.keys(selected).length} ${Object.keys(selected).length===1?'asset was':'assets were'} deposited.`);window.dispatchEvent(new Event('diplomatia:resources'));await Promise.all([loadAvailable(),reload()])}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const withdraw=(e:React.FormEvent)=>{e.preventDefault();mutate(`/alliances/${data.alliance.ID}/bank`,'POST',{kind:payoutKind,resource,amount,recipientNationID:recipient,memo})};
 const adjust=(e:React.FormEvent)=>{e.preventDefault();mutate(`/alliances/${data.alliance.ID}/member-balances/adjust`,'POST',{nationID:adjustNation,resource:adjustResource,amount:(adjustDirection==='subtract'?-1:1)*adjustAmount,memo:adjustMemo})};
 const ownBalances=data.memberBalances?.[data.permissions.nationID]||{},recipientBalances=data.memberBalances?.[recipient]||{};
 return <div className={'alliance-bank-page '+(!data.permissions.viewBank?'holdings-hidden ':'')+(!data.permissions.deposit?'deposit-hidden':'')}><div className="alliance-bank-layout">{data.permissions.deposit&&<form className="panel bank-deposit-panel" onSubmit={deposit}><header className="bank-panel-heading"><div><span className="eyebrow">NATIONAL TRANSFER</span><h2><ArrowDownToLine/> Make a deposit</h2></div><span>{Object.keys(selected).length} selected</span></header><div className="bank-deposit-ledger">{resources.map(key=>{const cash=key==='cash',onHand=Number(available[key]||0);return <label className="bank-deposit-row" key={key}><span className="bank-resource-name"><ResourceIcon type={bankResourceIcons[key]}/><span><b>{cash?'Treasury':label(key)}</b><small>On hand: {bankAmount(onHand,cash)} · Your bank balance: {bankAmount(Number(ownBalances[key]||0),cash)}</small></span></span><span className="bank-amount-entry"><input aria-label={`${label(key)} deposit amount`} type="number" min="0" max={onHand} step={cash?'1':'.001'} value={amounts[key]||''} placeholder="0" onChange={e=>setAmounts({...amounts,[key]:e.target.value})}/><button type="button" disabled={onHand<=0} onClick={()=>setAmounts({...amounts,[key]:cash?String(Math.floor(onHand)):String(Number(onHand.toFixed(3)))})}>Max</button></span></label>})}</div><div className="bank-deposit-footer"><p>Anything deposited becomes Alliance property. Returning funds or resources requires a member whose role has withdrawal authority.</p><label>Transaction note<input value={memo} maxLength={255} onChange={e=>setMemo(e.target.value)} placeholder="Optional note for the bank log"/></label>{error&&<p className="error">{error}</p>}{success&&<p className="bank-success">{success}</p>}<div><button type="button" onClick={()=>setAmounts({})}>Clear amounts</button><button className="primary" disabled={busy||!Object.keys(selected).length}><ArrowDownToLine/>{busy?'Depositing…':'Deposit selected'}</button></div></div></form>}{data.permissions.viewBank?<section className="panel bank-holdings-panel"><header className="bank-panel-heading"><div><span className="eyebrow">ALLIANCE TREASURY</span><h2><Landmark/> Current holdings</h2></div></header><div className="bank-holdings-ledger">{resources.map(key=><div className="bank-holding-row" key={key}><span><ResourceIcon type={bankResourceIcons[key]}/>{key==='cash'?'Treasury':label(key)}</span><b>{bankAmount(Number(data.bank[key]||0),key==='cash')}</b></div>)}</div></section>:<section className="panel bank-holdings-panel bank-holdings-private"><Landmark/><span className="eyebrow">ALLIANCE TREASURY</span><h2>Holdings are restricted</h2><p>Your current role does not permit viewing Alliance bank balances.</p></section>}</div>{data.permissions.withdraw&&<section className="panel bank-operations-panel"><nav className="bank-operation-tabs"><button className={operationTab==='withdraw'?'active':''} onClick={()=>setOperationTab('withdraw')}><ArrowUpFromLine/>Member payout</button><button className={operationTab==='adjust'?'active':''} onClick={()=>setOperationTab('adjust')}><WalletCards/>Adjust member balance</button></nav>{operationTab==='withdraw'?<form className="bank-withdraw-panel" onSubmit={withdraw}><div><span className="eyebrow">AUTHORIZED PAYOUT</span><h2>Withdraw from the Alliance bank</h2></div><label>Recipient nation<select value={recipient} onChange={e=>setRecipient(e.target.value)}>{data.members.map((member:any)=><option value={member.nationID} key={member.nationID}>{member.name}</option>)}</select></label><label>Asset<select value={resource} onChange={e=>setResource(e.target.value)}>{resources.map(key=><option value={key} key={key}>{key==='cash'?'Treasury':label(key)}</option>)}</select></label><label>Amount<input type="number" min={resource==='cash'?1:.001} step={resource==='cash'?1:.001} value={amount} onChange={e=>setAmount(Number(e.target.value))}/><small>Member balance: {bankAmount(Number(recipientBalances[resource]||0),resource==='cash')}</small></label><label>Payout treatment<select value={payoutKind} onChange={e=>setPayoutKind(e.target.value as 'withdrawal'|'grant')}><option value="withdrawal">Deduct member balance</option><option value="grant">Alliance grant</option></select></label><label>Transaction note<input value={memo} maxLength={255} onChange={e=>setMemo(e.target.value)} placeholder="Audit memo"/></label><button className="primary"><ArrowUpFromLine/>Issue payout</button></form>:<form className="bank-adjust-panel" onSubmit={adjust}><div><span className="eyebrow">INTERNAL MEMBER LEDGER</span><h2>Adjust a member balance</h2><p>This changes the member ledger only. Alliance bank holdings are not transferred.</p></div><label>Member nation<select value={adjustNation} onChange={e=>setAdjustNation(e.target.value)}>{data.members.map((member:any)=><option value={member.nationID} key={member.nationID}>{member.name}</option>)}</select></label><label>Asset<select value={adjustResource} onChange={e=>setAdjustResource(e.target.value)}>{resources.map(key=><option value={key} key={key}>{key==='cash'?'Treasury':label(key)}</option>)}</select></label><label>Adjustment<select value={adjustDirection} onChange={e=>setAdjustDirection(e.target.value as 'add'|'subtract')}><option value="add">Add to balance</option><option value="subtract">Subtract from balance</option></select></label><label>Amount<input type="number" min={adjustResource==='cash'?1:.001} step={adjustResource==='cash'?1:.001} value={adjustAmount||''} onChange={e=>setAdjustAmount(Number(e.target.value))}/><small>Current: {bankAmount(Number(data.memberBalances?.[adjustNation]?.[adjustResource]||0),adjustResource==='cash')}</small></label><label>Reason<input value={adjustMemo} required maxLength={255} onChange={e=>setAdjustMemo(e.target.value)} placeholder="Required audit reason"/></label><button className="primary" disabled={adjustAmount<=0}><WalletCards/>Save adjustment</button></form>}</section>}</div>
}

function BankTab({data,reload}:{data:any;mutate:Function;reload:()=>Promise<void>}){
 const initialView=data.permissions.viewBank?'holdings':data.permissions.withdraw?'payout':'member';
 const[view,setView]=useState<'holdings'|'member'|'payout'|'adjust'>(initialView),[available,setAvailable]=useState<Record<string,number>>({}),[depositAmounts,setDepositAmounts]=useState<Record<string,string>>({}),[depositMemo,setDepositMemo]=useState(''),[recipient,setRecipient]=useState(data.permissions.nationID),[payoutKind,setPayoutKind]=useState<'withdrawal'|'grant'>('withdrawal'),[payoutAmounts,setPayoutAmounts]=useState<Record<string,string>>({}),[payoutMemo,setPayoutMemo]=useState(''),[adjustNation,setAdjustNation]=useState(data.permissions.nationID),[adjustments,setAdjustments]=useState<Record<string,string>>({}),[adjustMemo,setAdjustMemo]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[success,setSuccess]=useState('');
 const loadAvailable=async()=>{const[me,strategy]=await Promise.all([call('/me'),call('/strategy')]);setAvailable({cash:Number(me.nation?.Treasury||0),...(strategy.stockpiles||{})})};
 useEffect(()=>{if(data.permissions.deposit)void loadAvailable().catch(e=>setError((e as Error).message))},[data.alliance.ID,data.permissions.deposit]);
 const ownBalances=data.memberBalances?.[data.permissions.nationID]||{},recipientBalances=data.memberBalances?.[recipient]||{},adjustedBalances=data.memberBalances?.[adjustNation]||{};
 const positiveEntries=(values:Record<string,string>)=>Object.fromEntries(resources.map(key=>[key,Number(values[key]||0)]).filter(([,value])=>Number(value)>0));
 const signedEntries=Object.fromEntries(resources.map(key=>[key,Number(adjustments[key]||0)]).filter(([,value])=>Number(value)!==0));
 const finish=async(message:string)=>{setSuccess(message);window.dispatchEvent(new Event('diplomatia:resources'));await Promise.all([loadAvailable(),reload()])};
 const deposit=async(e:React.FormEvent)=>{e.preventDefault();const deposits=positiveEntries(depositAmounts);if(!Object.keys(deposits).length){setError('Enter at least one deposit amount.');return}setBusy(true);setError('');setSuccess('');try{await call(`/alliances/${data.alliance.ID}/bank`,{method:'POST',body:JSON.stringify({kind:'deposit',deposits,memo:depositMemo})});setDepositAmounts({});setDepositMemo('');await finish('Deposit completed.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const payout=async(e:React.FormEvent)=>{e.preventDefault();const payouts=positiveEntries(payoutAmounts);if(!Object.keys(payouts).length){setError('Enter at least one payout amount.');return}setBusy(true);setError('');setSuccess('');try{await call(`/alliances/${data.alliance.ID}/bank`,{method:'POST',body:JSON.stringify({kind:payoutKind,recipientNationID:recipient,payouts,memo:payoutMemo})});setPayoutAmounts({});setPayoutMemo('');await finish('Multi-asset payout completed.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const adjust=async(e:React.FormEvent)=>{e.preventDefault();if(!Object.keys(signedEntries).length){setError('Enter at least one balance adjustment.');return}setBusy(true);setError('');setSuccess('');try{await call(`/alliances/${data.alliance.ID}/member-balances/adjust`,{method:'POST',body:JSON.stringify({nationID:adjustNation,adjustments:signedEntries,memo:adjustMemo})});setAdjustments({});setAdjustMemo('');await finish('Member balances updated.')}catch(e){setError((e as Error).message)}finally{setBusy(false)}};
 const row=(key:string,mode:'deposit'|'payout'|'adjust')=>{const cash=key==='cash',bankValue=Number(data.bank?.[key]||0),memberValue=Number((mode==='adjust'?adjustedBalances:mode==='payout'?recipientBalances:ownBalances)[key]||0),values=mode==='deposit'?depositAmounts:mode==='payout'?payoutAmounts:adjustments,setValues=mode==='deposit'?setDepositAmounts:mode==='payout'?setPayoutAmounts:setAdjustments,max=mode==='deposit'?Number(available[key]||0):mode==='payout'?(data.permissions.viewBank?(payoutKind==='withdrawal'?Math.min(bankValue,memberValue):bankValue):payoutKind==='withdrawal'?memberValue:undefined):undefined;return <label className="bank-ledger-input-row" key={key}><span className="bank-resource-name"><ResourceIcon type={bankResourceIcons[key]}/><span><b>{cash?'Treasury':label(key)}</b><small>{mode==='deposit'?`On hand: ${bankAmount(Number(available[key]||0),cash)} · Bank balance: ${bankAmount(memberValue,cash)}`:mode==='payout'?`${data.permissions.viewBank?`Alliance: ${bankAmount(bankValue,cash)} · `:''}Member: ${bankAmount(memberValue,cash)}`:`Current balance: ${bankAmount(memberValue,cash)}`}</small></span></span><span className="bank-amount-entry"><input aria-label={`${label(key)} ${mode} amount`} type="number" min={mode==='adjust'?undefined:0} max={max} step={cash?'1':'.001'} value={values[key]||''} placeholder={mode==='adjust'?'+ / −':'0'} onChange={e=>setValues({...values,[key]:e.target.value})}/>{mode!=='adjust'&&max!==undefined&&<button type="button" disabled={max<=0} onClick={()=>setValues({...values,[key]:cash?String(Math.floor(max)):String(Number(max.toFixed(3)))})}>Max</button>}</span></label>};
 return <div className={'alliance-bank-page '+(!data.permissions.deposit?'deposit-hidden':'')}><div className="alliance-bank-layout">{data.permissions.deposit&&<form className="panel bank-deposit-panel" onSubmit={deposit}><header className="bank-panel-heading"><div><span className="eyebrow">NATIONAL TRANSFER</span><h2><ArrowDownToLine/>Make a deposit</h2></div><span>{Object.keys(positiveEntries(depositAmounts)).length} selected</span></header><div className="bank-deposit-ledger">{resources.map(key=>row(key,'deposit'))}</div><div className="bank-deposit-footer"><p>Anything deposited becomes Alliance property. Returning funds or resources requires a member whose role has withdrawal authority.</p><label>Transaction note<input value={depositMemo} maxLength={255} onChange={e=>setDepositMemo(e.target.value)} placeholder="Optional bank-log note"/></label><div><button type="button" onClick={()=>setDepositAmounts({})}>Clear amounts</button><button className="primary" disabled={busy}>Deposit selected</button></div></div></form>}<section className="panel bank-treasury-card"><header className="bank-panel-heading"><div><span className="eyebrow">ALLIANCE TREASURY</span><h2><Landmark/>{view==='holdings'?'Current holdings':view==='member'?'Your bank balance':view==='payout'?'Member payout':'Adjust balances'}</h2></div></header>{(data.permissions.viewBank||data.permissions.withdraw)&&<nav className="bank-card-tabs">{data.permissions.viewBank&&<button className={view==='holdings'?'active':''} onClick={()=>setView('holdings')}>Holdings</button>}<button className={view==='member'?'active':''} onClick={()=>setView('member')}>My balance</button>{data.permissions.withdraw&&<><button className={view==='payout'?'active':''} onClick={()=>setView('payout')}>Payout</button><button className={view==='adjust'?'active':''} onClick={()=>setView('adjust')}>Adjust balances</button></>}</nav>}{view==='holdings'&&<div className="bank-holdings-ledger">{resources.map(key=><div className="bank-holding-row" key={key}><span><ResourceIcon type={bankResourceIcons[key]}/>{key==='cash'?'Treasury':label(key)}</span><b>{bankAmount(Number(data.bank[key]||0),key==='cash')}</b></div>)}</div>}{view==='member'&&<div className="bank-holdings-ledger">{resources.map(key=><div className="bank-holding-row" key={key}><span><ResourceIcon type={bankResourceIcons[key]}/>{key==='cash'?'Treasury':label(key)}</span><b>{bankAmount(Number(ownBalances[key]||0),key==='cash')}</b></div>)}</div>}{view==='payout'&&<form onSubmit={payout}><div className="bank-ledger-toolbar"><label>Recipient nation<select value={recipient} onChange={e=>setRecipient(e.target.value)}>{data.members.map((member:any)=><option value={member.nationID} key={member.nationID}>{member.name}</option>)}</select></label><label>Payout treatment<select value={payoutKind} onChange={e=>setPayoutKind(e.target.value as 'withdrawal'|'grant')}><option value="withdrawal">Deduct member balance</option><option value="grant">Alliance grant</option></select></label></div><div className="bank-deposit-ledger">{resources.map(key=>row(key,'payout'))}</div><div className="bank-deposit-footer"><p>{payoutKind==='withdrawal'?'This payout reduces the selected nation’s tracked balances.':'This grant leaves the selected nation’s tracked balances unchanged.'}</p><label>Transaction note<input value={payoutMemo} maxLength={255} onChange={e=>setPayoutMemo(e.target.value)} placeholder="Optional bank-log note"/></label><div><button type="button" onClick={()=>setPayoutAmounts({})}>Clear amounts</button><button className="primary" disabled={busy}>Issue selected payout</button></div></div></form>}{view==='adjust'&&<form onSubmit={adjust}><div className="bank-ledger-toolbar"><label>Member nation<select value={adjustNation} onChange={e=>setAdjustNation(e.target.value)}>{data.members.map((member:any)=><option value={member.nationID} key={member.nationID}>{member.name}</option>)}</select></label><p>Use positive amounts to add to a balance and negative amounts to subtract.</p></div><div className="bank-deposit-ledger">{resources.map(key=>row(key,'adjust'))}</div><div className="bank-deposit-footer"><p>Adjustments change the internal member ledger only. Alliance bank holdings are not transferred.</p><label>Audit reason<input required value={adjustMemo} maxLength={255} onChange={e=>setAdjustMemo(e.target.value)} placeholder="Reason for this adjustment"/></label><div><button type="button" onClick={()=>setAdjustments({})}>Clear amounts</button><button className="primary" disabled={busy}>Save selected adjustments</button></div></div></form>}</section></div>{error&&<p className="error notice">{error}</p>}{success&&<p className="bank-success notice">{success}</p>}</div>;
}

function TaxTab({data,mutate}:{data:any;mutate:Function}){const fallback=data.taxBrackets.find((b:any)=>b.isDefault);return <section className="panel"><span className="eyebrow">TAX POLICY</span><h2>Brackets and member assignments</h2><p>Create reusable tax brackets first, then assign each member to one of them. Members without a custom assignment use the protected default bracket.</p><div className="tax-bracket-definitions">{data.taxBrackets.map((b:any)=><TaxBracket key={b.id} bracket={b} editable={data.permissions.tax} allianceID={data.alliance.ID} mutate={mutate}/>)}</div>{data.permissions.tax&&<NewTaxBracket allianceID={data.alliance.ID} mutate={mutate}/>}<div className="member-tax-assignments"><span className="eyebrow">MEMBER ASSIGNMENTS</span><h3>Assign existing brackets</h3>{data.members.map((member:any)=><label key={member.nationID}><span><b>{member.name}</b><small>{member.role}</small></span><select value={member.taxBracketID||fallback?.id||''} disabled={!data.permissions.tax} onChange={e=>mutate(`/alliances/${data.alliance.ID}/members/${member.nationID}/tax-bracket`,'PATCH',{bracketID:e.target.value})}>{data.taxBrackets.map((bracket:any)=><option key={bracket.id} value={bracket.id}>{bracket.name}{bracket.isDefault?' (Default)':''}</option>)}</select></label>)}</div></section>}
function TaxHistory({data}:{data:any}){const[page,setPage]=useState(1),items=data.taxHistory||[],visible=items.slice((page-1)*10,page*10);return <section className="panel"><span className="eyebrow">TAX HISTORY</span><h2>Automatic collections</h2>{items.length?visible.map((item:any,i:number)=><div className="tax-history-row" key={`${item.createdAt}-${i}`}><time>{new Date(item.createdAt).toLocaleString()}</time><b>{item.nation}</b><span>{label(item.resource)}</span><strong>{Number(item.amount).toLocaleString()}</strong><small>{item.memo}</small></div>):<p>No tax collections have been recorded.</p>}<ListPager page={page} total={items.length} setPage={setPage} label="Tax history"/></section>}
function TaxBracket({bracket,editable,allianceID,mutate}:{bracket:any;editable:boolean;allianceID:string;mutate:Function}){return <form className="tax-bracket" onSubmit={e=>{e.preventDefault();mutate(`/alliances/${allianceID}/tax-brackets/${bracket.id}`,'PATCH',taxBracketPayload(e.currentTarget))}}><input name="name" defaultValue={bracket.name} disabled={!editable}/><div className="tax-bracket-member">{bracket.isDefault?'Fallback bracket':`${bracket.assignedCount||0} members assigned`}</div><label>Cash %<input name="cashRate" type="number" min="0" max="100" step=".1" defaultValue={bracket.cashRate} disabled={!editable} required/></label><label>Resources %<input name="resourceRate" type="number" min="0" max="100" step=".1" defaultValue={bracket.resourceRate} disabled={!editable} required/></label>{editable&&<button>Save</button>}{editable&&!bracket.isDefault&&<button type="button" className="danger" onClick={()=>confirm('Delete this bracket? Assigned members will return to the default bracket.')&&mutate(`/alliances/${allianceID}/tax-brackets/${bracket.id}`,'DELETE')}>Delete</button>}{bracket.isDefault&&<small>Protected default</small>}</form>}
function NewTaxBracket({allianceID,mutate}:{allianceID:string;mutate:Function}){return <details className="new-bracket"><summary><Plus/>Create tax bracket</summary><form onSubmit={e=>{e.preventDefault();mutate(`/alliances/${allianceID}/tax-brackets`,'POST',taxBracketPayload(e.currentTarget))}}><input name="name" placeholder="Bracket name" required/><input name="cashRate" aria-label="Cash tax percent" type="number" min="0" max="100" step=".1" defaultValue="0" required/><input name="resourceRate" aria-label="Resource tax percent" type="number" min="0" max="100" step=".1" defaultValue="0" required/><button className="primary">Create bracket</button></form></details>}

const permissionFields=[['viewBank','View Bank Amounts'],['deposit','Deposit'],['withdraw','Withdraw'],['applicants','Applicants'],['remove','Remove Members'],['edit','Edit Details'],['roles','Manage Roles'],['tax','Set Tax'],['promote','Promote/Demote'],['announcements','Announcements'],['audit','View Bank Logs'],['war','War & Treaties']] as const;
function RolesTab({data,mutate}:{data:any;mutate:Function}){return <section className="panel roles-panel"><span className="eyebrow">DATA-DRIVEN HIERARCHY</span><h2>Roles and permissions</h2>{data.roles.map((role:any)=><RoleEditor key={role.id} role={role} allianceID={data.alliance.ID} actorRank={data.permissions.rank} mutate={mutate}/>)}<NewRole allianceID={data.alliance.ID} actorRank={data.permissions.rank} mutate={mutate}/></section>}
function RoleEditor({role,allianceID,actorRank,mutate}:{role:any;allianceID:string;actorRank:number;mutate:Function}){const p=role.permissions||{};return <form className="role-editor" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),body:any={name:f.get('name'),rank:Number(f.get('rank')),withdrawalLimit:Number(f.get('withdrawalLimit'))};for(const[key]of permissionFields)body[key]=f.get(key)==='on';mutate(`/alliances/${allianceID}/roles/${role.id}`,'PATCH',body)}}><div className="role-identity"><input name="name" defaultValue={role.title}/><label>Rank<input name="rank" type="number" min="0" max={actorRank} defaultValue={role.rank} disabled={role.defaultKey==='leader'||role.defaultKey==='applicant'}/></label><span>{role.defaultKey?`Protected ${role.defaultKey}`:'Custom role'}</span></div><div className="permission-grid">{permissionFields.map(([key,name])=><label key={key}><input name={key} type="checkbox" defaultChecked={Boolean(p[key])}/>{name}</label>)}<label>Daily withdrawal limit<input name="withdrawalLimit" type="number" min="0" defaultValue={p.withdrawalLimit||0}/></label></div><div><button className="primary">Save role</button>{!role.defaultKey&&<button type="button" className="danger" onClick={()=>mutate(`/alliances/${allianceID}/roles/${role.id}`,'DELETE')}>Delete role</button>}</div></form>}
function NewRole({allianceID,actorRank,mutate}:{allianceID:string;actorRank:number;mutate:Function}){return <details className="new-role"><summary><Plus/>Create custom role</summary><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);mutate(`/alliances/${allianceID}/roles`,'POST',{name:f.get('name'),rank:Number(f.get('rank')),deposit:true})}}><input name="name" placeholder="Role name" required/><input name="rank" type="number" min="1" max={actorRank-1} placeholder="Rank order" required/><button className="primary">Create role</button></form></details>}

function ApplicationsTab({data,mutate}:{data:any;mutate:Function}){return <section className="panel"><span className="eyebrow">PENDING APPLICANTS</span><h2>Membership applications</h2>{data.applications.length?data.applications.map((item:any)=><div className="application-row" key={item.id}><div><b>{item.nation}</b><p>{item.message||'No application message.'}</p></div><div><button className="primary" onClick={()=>mutate(`/alliances/${data.alliance.ID}/applications/${item.id}/accept`)}>Accept</button><button className="danger" onClick={()=>mutate(`/alliances/${data.alliance.ID}/applications/${item.id}/reject`)}>Reject</button></div></div>):<p>No pending applications.</p>}</section>}
function BankLogs({data}:{data:any}){const[page,setPage]=useState(1),items=data.transactions||[],visible=items.slice((page-1)*10,page*10);return <section className="panel"><span className="eyebrow">SENSITIVE AUDIT HISTORY</span><h2>Bank transaction log</h2>{items.length?visible.map((item:any,i:number)=><div className="bank-log" key={`${item.createdAt}-${i}`}><time>{new Date(item.createdAt).toLocaleString()}</time>{item.actorID?<a href={`/nation/${item.actorID}`} onClick={e=>{e.preventDefault();go(`/nation/${item.actorID}`)}}><b>{item.actor}</b></a>:<b>{item.actor}</b>}<span>{label(item.kind)}</span><strong>{item.resource==='cash'?'¥':''}{Number(item.amount).toLocaleString(undefined,{maximumFractionDigits:3})} {label(item.resource)}</strong><small>{item.recipient&&<>For <a href={`/nation/${item.recipientID}`} onClick={e=>{e.preventDefault();go(`/nation/${item.recipientID}`)}}>{item.recipient}</a>{item.memo?' · ':''}</>}{item.memo}</small></div>):<p>No bank transactions have been recorded.</p>}<ListPager page={page} total={items.length} setPage={setPage} label="Bank transaction log"/></section>}
function AllianceSettings({alliance,save,reload}:{alliance:any;save:(body:any)=>void;reload:()=>void}){const[message,setMessage]=useState(''),[uploading,setUploading]=useState(false);const upload=async(event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024){setMessage('Choose a PNG or JPEG flag under 2 MB.');event.target.value='';return}setUploading(true);try{const body=new FormData();body.append('flag',file);const response=await fetch(`/api/alliances/${encodeURIComponent(alliance.ID)}/flag`,{method:'POST',credentials:'include',body});const result=await response.json().catch(()=>({}));if(!response.ok)throw Error(result.error||'Could not upload this Alliance flag.');setMessage('Alliance flag updated.');reload()}catch(error){setMessage((error as Error).message)}finally{setUploading(false);event.target.value=''}};return <section className="panel alliance-settings"><span className="eyebrow">ALLIANCE ADMINISTRATION</span><h2>Edit Alliance details</h2><section className="alliance-flag-editor"><AllianceFlag id={alliance.ID} name={alliance.Name} className="alliance-editor-flag"/><div><span className="eyebrow">ALLIANCE FLAG</span><h3>Alliance standard</h3><p>Upload a PNG or JPEG under 2 MB. Use a 1.2:1 to 2.5:1 flag ratio; 120–2,400 px per side.</p><label className="flag-upload-control"><input type="file" accept="image/png,image/jpeg" onChange={upload} disabled={uploading}/><span>{uploading?'Uploading flag…':'Upload Alliance flag'}</span></label></div></section>{message&&<p className="notice">{message}</p>}<form onSubmit={e=>{e.preventDefault();save(Object.fromEntries(new FormData(e.currentTarget)))}}><label className="alliance-description-field">Public Alliance description<textarea name="description" defaultValue={alliance.Description} maxLength={5000} rows={14} placeholder="Describe your Alliance, its purpose, expectations, and diplomatic identity…"/><small>Safe BBCode: [b], [i], [u], [color=#hex], [url=https://…], [list][*]item[/list] · Maximum 5,000 characters</small></label><div className="alliance-settings-row"><label>Membership policy<select name="joinPolicy" defaultValue={alliance.JoinPolicy}><option value="open">Open membership</option><option value="apply">Applications required</option><option value="invite_only">Invite only</option></select></label><label>Community URL<input name="communityURL" type="url" defaultValue={alliance.CommunityURL} placeholder="https://…"/></label></div><button className="primary alliance-settings-save">Save Alliance details</button></form></section>}
function AllianceShare({alliance}:{alliance:any}){const path=`/alliance/${encodeURIComponent(alliance.ID)}`,url=location.origin+path;return <section className="share-identity"><div><span>Alliance ID</span><code>{alliance.ID}</code></div><div><span>Shareable Alliance link</span><a href={path}>{url}</a></div><button onClick={()=>navigator.clipboard.writeText(url)}>Copy link</button></section>}
